export function accounts():AccountRecord[]{return Object.entries(ids).map(([key,id])=>({id,loginId:'시험'+key,loginIdKey:'시험'+key,displayName:key==='applicant'||key==='guest'?'동명이인':'시험 '+key,homeClubId:key==='master'?null:key==='guest'?clubs[1].id:clubs[0].id,kind:'regular',isMaster:key==='master',homeRole:key==='operator'||key==='multi'?'staff':null,grants:key==='multi'?[{clubId:clubs[1].id,role:'staff'}]:[],active:true,passwordHash:'unused-test-hash',mustChangePassword:false,temporaryExpiresAt:null,authVersion:1}))}
